/**
 * Dataverse access for the two tables the admin manages: Adopta Setting and Adopta Audience Group.
 * The services are generated by the Power Apps CLI (setup.ps1).
 */
import type { IOperationResult } from "@microsoft/power-apps/data";
import type { Vm_adoptaaudiencegroupsvm_grouptype } from "../generated/models/Vm_adoptaaudiencegroupsModel";
import { dataSourcesInfo } from "../../.power/schemas/appschemas/dataSourcesInfo";
import { services } from "../../../shared/power-apps";
import { edition } from "../../../shared/edition";
import { currentLanguage, text, toLanguage, type Language } from "../i18n";

const bound = services(dataSourcesInfo);
const GroupsService = bound.table("vm_adoptaaudiencegroups")();
const SettingsService = bound.table("vm_adoptasettings")();

export interface SettingsForm {
  name: string;
  appTitle: string;
  agentName: string;
  /** vm_defaultlanguage: app fallback only, never the agent or card language. */
  defaultLanguage: Language;
  coachKnowledgeUrl: string;
  sendingEnabled: boolean;
}

export interface SettingsRecord extends SettingsForm {
  id: string;
  applyStatus: string;
  appliedOn?: string;
}

export interface SettingsState {
  /** The first active record by creation date: the one app, agent and flows use. */
  record?: SettingsRecord;
  activeCount: number;
}

export type GroupType = Vm_adoptaaudiencegroupsvm_grouptype;

export const GROUP_TYPES: { value: GroupType; label: () => string }[] = [
  { value: 100000001, label: () => text().data.securityGroup },
  { value: 100000000, label: () => "Microsoft 365" },
];

export interface GroupForm {
  name: string;
  entraObjectId: string;
  type: GroupType;
  enabled: boolean;
}

export interface GroupRecord extends GroupForm {
  id: string;
}

/** Form of a configuration not created yet. Its name and language follow the app language. */
export function emptySettings(): SettingsForm {
  return {
    name: text().data.defaultName,
    appTitle: "",
    agentName: "",
    defaultLanguage: currentLanguage(),
    coachKnowledgeUrl: "",
    sendingEnabled: false,
  };
}

export const EMPTY_GROUP: GroupForm = { name: "", entraObjectId: "", type: 100000001, enabled: true };

export const HTTPS_LINK = /^https:\/\/\S+$/;
export const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const SETTINGS_COLUMNS = [
  "vm_adoptasettingid",
  "vm_name",
  "vm_apptitle",
  "vm_agentname",
  "vm_defaultlanguage",
  "vm_coachknowledgeurl",
  "vm_sendingenabled",
  "vm_applystatus",
  "vm_appliedon",
];

function check<T>(result: IOperationResult<T>, action: string): T {
  if (!result.success) {
    const message = result.error?.message ?? text().common.unknownError;
    // Missing privileges come back as "... is missing prvWrite... privilege".
    const hint = /\bprv[A-Z]/.test(message) ? text().data.adminRoleHint : "";
    throw new Error(`${action}: ${message}${hint}`);
  }
  return result.data;
}

type SettingsRow = {
  vm_adoptasettingid: string;
  vm_name?: string | null;
  vm_apptitle?: string | null;
  vm_agentname?: string | null;
  vm_defaultlanguage?: string | null;
  vm_coachknowledgeurl?: string | null;
  vm_sendingenabled?: boolean | null;
  vm_applystatus?: string | null;
  vm_appliedon?: string | null;
};

function toSettings(row: SettingsRow): SettingsRecord {
  return {
    id: row.vm_adoptasettingid,
    name: row.vm_name ?? "",
    appTitle: row.vm_apptitle ?? "",
    agentName: row.vm_agentname ?? "",
    defaultLanguage: toLanguage(row.vm_defaultlanguage) ?? edition().language,
    coachKnowledgeUrl: row.vm_coachknowledgeurl ?? "",
    sendingEnabled: row.vm_sendingenabled === true,
    applyStatus: row.vm_applystatus ?? "",
    appliedOn: row.vm_appliedon ?? undefined,
  };
}

function settingsFields(form: SettingsForm) {
  return {
    vm_name: form.name.trim() || text().data.defaultName,
    vm_apptitle: form.appTitle.trim(),
    vm_agentname: form.agentName.trim(),
    vm_defaultlanguage: form.defaultLanguage,
    vm_coachknowledgeurl: form.coachKnowledgeUrl.trim(),
    vm_sendingenabled: form.sendingEnabled,
  };
}

export async function loadSettings(): Promise<SettingsState> {
  const rows = check(
    await SettingsService.getAll({ select: SETTINGS_COLUMNS, filter: "statecode eq 0", orderBy: ["createdon asc"] }),
    text().data.readSettings,
  ) as SettingsRow[];
  return { record: rows[0] ? toSettings(rows[0]) : undefined, activeCount: rows.length };
}

export async function readSettings(id: string): Promise<SettingsRecord> {
  return toSettings(check(await SettingsService.get(id, { select: SETTINGS_COLUMNS }), text().data.readSettings) as SettingsRow);
}

/** Creates the record or updates only the changed columns. Returns the record id. */
export async function saveSettings(form: SettingsForm, saved?: SettingsRecord): Promise<string> {
  const fields = settingsFields(form);
  if (!saved) {
    const created = check(await SettingsService.create({ statecode: 0, ...fields }), text().data.createSettings);
    if (!created || typeof created !== "object" || !("vm_adoptasettingid" in created) || typeof created.vm_adoptasettingid !== "string") {
      throw new Error(text().common.unknownError + ": missing setting ID");
    }
    return created.vm_adoptasettingid;
  }
  const before = settingsFields(saved);
  const changed = Object.fromEntries(
    Object.entries(fields).filter(([key, value]) => before[key as keyof typeof before] !== value),
  );
  if (Object.keys(changed).length > 0) {
    check(await SettingsService.update(saved.id, changed), text().data.saveSettings);
  }
  return saved.id;
}

/** True when the change starts AdoptaApplySettings (its trigger filters on these columns). */
export function triggersApply(form: SettingsForm, saved?: SettingsRecord): boolean {
  if (!saved) return true;
  const a = settingsFields(form);
  const b = settingsFields(saved);
  return a.vm_name !== b.vm_name || a.vm_apptitle !== b.vm_apptitle || a.vm_agentname !== b.vm_agentname || a.vm_coachknowledgeurl !== b.vm_coachknowledgeurl;
}

function imageType(bytes: Uint8Array): string {
  if (bytes[0] === 0x89 && bytes[1] === 0x50) return "image/png";
  if (bytes[0] === 0xff && bytes[1] === 0xd8) return "image/jpeg";
  if (bytes[0] === 0x47 && bytes[1] === 0x49) return "image/gif";
  return "application/octet-stream";
}

/** Object URL of the logo, or undefined when none is uploaded. The caller revokes it. */
export async function loadLogo(id: string): Promise<string | undefined> {
  try {
    const image = await SettingsService.downloadImage(id, "vm_logo", true);
    if (!image.success || !image.data?.length) return undefined;
    const bytes = new Uint8Array(image.data);
    return URL.createObjectURL(new Blob([bytes], { type: imageType(bytes) }));
  } catch {
    return undefined;
  }
}

export async function uploadLogo(id: string, file: File): Promise<void> {
  check(await SettingsService.upload(id, "vm_logo", file), text().data.uploadLogo);
}

export async function removeLogo(id: string): Promise<void> {
  check(await SettingsService.deleteFileOrImage(id, "vm_logo"), text().data.removeLogo);
}

type GroupRow = {
  vm_adoptaaudiencegroupid: string;
  vm_name?: string | null;
  vm_entraobject?: string | null;
  vm_grouptype?: GroupType | null;
  vm_enabled?: boolean | null;
};

export async function listGroups(): Promise<GroupRecord[]> {
  const rows = check(
    await GroupsService.getAll({
      select: ["vm_adoptaaudiencegroupid", "vm_name", "vm_entraobject", "vm_grouptype", "vm_enabled"],
      filter: "statecode eq 0",
      orderBy: ["vm_name asc"],
    }),
    text().data.readGroups,
  ) as GroupRow[];
  return rows.map((row) => ({
    id: row.vm_adoptaaudiencegroupid,
    name: row.vm_name ?? "",
    entraObjectId: row.vm_entraobject ?? "",
    type: row.vm_grouptype ?? EMPTY_GROUP.type,
    enabled: row.vm_enabled === true,
  }));
}

export async function saveGroup(form: GroupForm, id?: string): Promise<void> {
  const fields = {
    vm_name: form.name.trim(),
    vm_entraobject: form.entraObjectId.trim().toLowerCase(),
    vm_grouptype: form.type,
    vm_enabled: form.enabled,
  };
  if (id) check(await GroupsService.update(id, fields), text().data.saveGroup);
  else check(await GroupsService.create({ statecode: 0, ...fields }), text().data.createGroup);
}

export async function setGroupEnabled(id: string, enabled: boolean): Promise<void> {
  check(await GroupsService.update(id, { vm_enabled: enabled }), text().data.saveGroup);
}

export async function deleteGroup(id: string): Promise<void> {
  check(await GroupsService.delete(id), text().data.deleteGroup);
}
